<template><section class="scr-card"><h3>{{ t('settings.seed') }}</h3><label class="scr-field"><span>{{ t('settings.locale') }}</span><select :value="preferences.locale || 'auto'" @change="locale($event.target.value)"><option value="auto">{{ t('settings.localeAuto') }}</option><option value="en-US">English (United States)</option><option value="pt-BR">Português (Brasil)</option></select></label><label class="scr-field"><span>{{ t('settings.fixedSeed') }}</span><select :value="settings.seedMode" @change="update('seedMode', $event.target.value)"><option value="random">{{ t('settings.randomSeed') }}</option><option value="fixed">{{ t('settings.fixedSeed') }}</option></select></label><label class="scr-field"><span>{{ t('settings.manualSeed') }}</span><input :value="settings.manualSeed" maxlength="128" :disabled="settings.seedMode !== 'fixed'" @change="update('manualSeed', $event.target.value)" /></label><NumericInput :model-value="Number(settings.chaos || 75)" :label="t('settings.chaos')" :min="0" :max="100" @update:model-value="value => update('chaos', value)" /></section></template>
<script setup>import { useStores } from "../../stores"; import NumericInput from "../common/NumericInput.vue"; const stores = useStores(); const settings = stores.settings.state; const preferences = settings.uiPreferences || {}; const { t } = stores.i18n; const update = (field, value) => stores.command.send("updateSettings", [{ [field]: value }]); function locale(value) { stores.i18n.setPreference(value); stores.command.send("updateUIPreferences", [{ locale: value }]) }</script>
